const fs = require('fs');
const o = JSON.parse(fs.readFileSync('./cxte9.json', 'utf8'));
const ruling = fs.readFileSync('./cxte9-ruling.md', 'utf8');
const merged = o.description.replace(/\s+$/, '') + '\r\n\r\n' + ruling.replace(/\r?\n/g, '\r\n').replace(/\s+$/, '') + '\r\n';
fs.writeFileSync('./cxte9-desc.md', merged, 'utf8');
const rep = [
  'identifier=' + o.identifier,
  'status=' + o.status,
  'assignee_id=' + o.assignee_id,
  'parent=' + o.parent_issue_id,
  'orig_desc_len=' + o.description.length,
  'merged_len=' + merged.length,
  'replacement_chars=' + ((merged.match(/\uFFFD/g) || []).length),
  'question_runs=' + ((merged.match(/\?\?/g) || []).length),
  'has_env_properties=' + merged.includes('env.properties'),
  'has_ruling_marker=' + merged.includes('人类裁决已就位'),
  'desc_head=' + o.description.slice(0, 40),
  'desc_tail=' + o.description.slice(-60),
  'merged_tail=' + merged.slice(-70)
].join('\n');
fs.writeFileSync('./merge-report.txt', rep, 'utf8');

